"""Safety verification with Spacer/PDR over transition systems and Horn files."""

from __future__ import annotations

from pathlib import Path

import z3

from framework import report_result


def _state_vars(prefix: str, state_sorts) -> list[z3.ExprRef]:
    return [z3.Const(f"{prefix}{index}", sort) for index, sort in enumerate(state_sorts)]


def _as_state_formula(spec, current_state, next_state=None):
    if callable(spec):
        if next_state is None:
            return spec(current_state)
        return spec(current_state, next_state)
    return spec


def verify_transition_system(name, state_sorts, init_cond, trans_rel, safety_prop):
    """Verify a transition system with Spacer and return safety metadata."""
    fp = z3.Fixedpoint()
    fp.set(engine="spacer")

    current_state = _state_vars(f"{name}_s_", state_sorts)
    next_state = _state_vars(f"{name}_sp_", state_sorts)
    inv = z3.Function(f"{name}_Inv", *state_sorts, z3.BoolSort())
    error = z3.Function(f"{name}_Error", z3.BoolSort())

    fp.register_relation(inv, error)
    fp.declare_var(*(current_state + next_state))
    fp.rule(inv(*current_state), _as_state_formula(init_cond, current_state))
    fp.rule(
        inv(*next_state),
        [inv(*current_state), _as_state_formula(trans_rel, current_state, next_state)],
    )
    fp.rule(
        error(),
        [inv(*current_state), z3.Not(_as_state_formula(safety_prop, current_state))],
    )

    result = fp.query(error())
    invariant = str(fp.get_answer()) if result == z3.unsat else None
    return {"safe": result == z3.unsat, "invariant": invariant}


def verify_horn_file(filepath):
    """Verify a Horn benchmark file with Spacer."""
    fp = z3.Fixedpoint()
    fp.set(engine="spacer")
    queries = fp.parse_file(str(filepath))
    safe = True
    for query in queries:
        if fp.query(query) == z3.sat:
            safe = False
            break
    return {"safe": safe}


def build_counter_system(bound, safety_limit):
    """Build a bounded counter system that stutters once it reaches the bound."""
    sorts = [z3.IntSort()]

    def init(state):
        (x,) = state
        return x == 0

    def trans(state, next_state):
        (x,) = state
        (xp,) = next_state
        return z3.Or(z3.And(x < bound, xp == x + 1), z3.And(x >= bound, xp == x))

    def safety(state):
        (x,) = state
        return x < safety_limit

    return sorts, init, trans, safety


def build_bakery_system():
    """Build the 2-process Lamport Bakery mutual exclusion system."""
    sorts = [z3.IntSort(), z3.IntSort(), z3.IntSort(), z3.IntSort()]

    def init(state):
        pc1, pc2, y1, y2 = state
        return z3.And(pc1 == 0, pc2 == 0, y1 == 0, y2 == 0)

    def trans(state, next_state):
        pc1, pc2, y1, y2 = state
        pc1p, pc2p, y1p, y2p = next_state
        p1_enter = z3.And(pc1 == 0, pc1p == 1, pc2p == pc2, y1p == y2 + 1, y2p == y2)
        p1_wait = z3.And(
            pc1 == 1,
            z3.Or(y2 == 0, y1 <= y2),
            pc1p == 2,
            pc2p == pc2,
            y1p == y1,
            y2p == y2,
        )
        p1_exit = z3.And(pc1 == 2, pc1p == 0, pc2p == pc2, y1p == 0, y2p == y2)
        p2_enter = z3.And(pc2 == 0, pc2p == 1, pc1p == pc1, y2p == y1 + 1, y1p == y1)
        p2_wait = z3.And(
            pc2 == 1,
            z3.Or(y1 == 0, y2 < y1),
            pc2p == 2,
            pc1p == pc1,
            y1p == y1,
            y2p == y2,
        )
        p2_exit = z3.And(pc2 == 2, pc2p == 0, pc1p == pc1, y1p == y1, y2p == 0)
        return z3.Or(p1_enter, p1_wait, p1_exit, p2_enter, p2_wait, p2_exit)

    def safety(state):
        pc1, pc2, _y1, _y2 = state
        return z3.Not(z3.And(pc1 == 2, pc2 == 2))

    return sorts, init, trans, safety


def build_double_inc_system():
    """Build an unsafe system where x and y grow without bound."""
    sorts = [z3.IntSort(), z3.IntSort()]

    def init(state):
        x, y = state
        return z3.And(x == 0, y == 0)

    def trans(state, next_state):
        x, y = state
        xp, yp = next_state
        return z3.And(xp == x + 1, yp == y + 2)

    def safety(state):
        x, y = state
        return x + y < 50

    return sorts, init, trans, safety


def run_spacer_experiments() -> dict[str, int]:
    """Run the Spacer experiments and report their metrics."""
    benchmark_root = Path(__file__).resolve().parent.parent / "benchmarks"
    systems = [
        ("counter_safe", build_counter_system(10, 20)),
        ("counter_unsafe", build_counter_system(10, 5)),
        ("bakery", build_bakery_system()),
        ("double_inc", build_double_inc_system()),
        ("counter_large_safe", build_counter_system(100, 200)),
    ]
    horn_files = [
        "counter_safe.smt2",
        "counter_unsafe.smt2",
        "two_var_safe.smt2",
        "bakery_mutex.smt2",
        "double_counter_unsafe.smt2",
    ]

    verification_results = {
        name: verify_transition_system(name, *system) for name, system in systems
    }
    results = {
        "SPACER_SAFE_SYSTEMS": sum(
            1 for outcome in verification_results.values() if outcome["safe"]
        ),
        "SPACER_HORN_SAFE": sum(
            1 for horn_file in horn_files if verify_horn_file(benchmark_root / horn_file)["safe"]
        ),
        "SPACER_BAKERY_SAFE": 1 if verification_results["bakery"]["safe"] else 0,
    }
    for key, value in results.items():
        report_result(key, value)
    return results


if __name__ == "__main__":
    run_spacer_experiments()

"""SMT-based solving and optimization experiments built on Z3."""

from __future__ import annotations

from z3 import Distinct, If, Implies, Int, Optimize, Or, Solver, sat

from framework import PETERSEN_GRAPH, report_result


def count_nqueens_solutions(n: int) -> int:
    """Count all N-Queens solutions by blocking each discovered model."""
    solver = Solver()
    queens = [Int(f"q_{idx}") for idx in range(n)]

    for queen in queens:
        solver.add(queen >= 0, queen < n)

    solver.add(Distinct(*queens))
    for row in range(n):
        for other_row in range(row + 1, n):
            distance = other_row - row
            solver.add(queens[row] - queens[other_row] != distance)
            solver.add(queens[row] - queens[other_row] != -distance)

    count = 0
    while solver.check() == sat:
        model = solver.model()
        solution = [model.eval(queen).as_long() for queen in queens]
        solver.add(Or(*[queen != value for queen, value in zip(queens, solution)]))
        count += 1

    return count


def chromatic_number(graph) -> int:
    """Return the minimum number of colors needed to color the graph."""
    for num_colors in range(1, graph.num_nodes() + 1):
        solver = Solver()
        colors = {node: Int(f"color_{node}") for node in graph.nodes}

        for node in graph.nodes:
            solver.add(colors[node] >= 0, colors[node] < num_colors)

        for source, target in graph.edges:
            solver.add(colors[source] != colors[target])

        if solver.check() == sat:
            return num_colors

    raise ValueError("graph coloring unexpectedly unsatisfiable")


def schedule_jobs(jobs, num_machines: int) -> int:
    """Minimize makespan for non-overlapping jobs on identical machines."""
    optimizer = Optimize()
    starts = {job_id: Int(f"start_{job_id}") for job_id, _ in jobs}
    machines = {job_id: Int(f"machine_{job_id}") for job_id, _ in jobs}
    makespan = Int("makespan")

    for job_id, duration in jobs:
        optimizer.add(starts[job_id] >= 0)
        optimizer.add(machines[job_id] >= 0, machines[job_id] < num_machines)
        optimizer.add(makespan >= starts[job_id] + duration)

    for index, (job_id, duration) in enumerate(jobs):
        for other_job_id, other_duration in jobs[index + 1:]:
            job_ends_before_other = starts[job_id] + duration <= starts[other_job_id]
            other_ends_before_job = starts[other_job_id] + other_duration <= starts[job_id]
            optimizer.add(
                Implies(
                    machines[job_id] == machines[other_job_id],
                    Or(job_ends_before_other, other_ends_before_job),
                )
            )

    optimizer.minimize(makespan)
    if optimizer.check() != sat:
        raise ValueError("job scheduling instance is unsatisfiable")

    return optimizer.model().eval(makespan).as_long()


def run_z3_experiments() -> None:
    """Run the SMT solver experiment suite."""
    jobs = [("A", 3), ("B", 5), ("C", 2), ("D", 4), ("E", 6), ("F", 1)]
    report_result("Z3_NQUEENS_8_SOLUTIONS", count_nqueens_solutions(8))
    report_result("Z3_PETERSEN_CHROMATIC", chromatic_number(PETERSEN_GRAPH))
    report_result("Z3_SCHEDULE_MAKESPAN", schedule_jobs(jobs, 3))


if __name__ == "__main__":
    run_z3_experiments()

