"""Imperative-to-Horn translation and verification utilities."""

from __future__ import annotations

from dataclasses import dataclass, field
import re
from typing import Iterator

import z3


@dataclass(frozen=True)
class Variable:
    name: str


@dataclass(frozen=True)
class Const:
    value: int | bool


@dataclass(frozen=True)
class BinOp:
    op: str
    left: object
    right: object | None = None


@dataclass(frozen=True)
class Assign:
    var_name: str
    expr: object


@dataclass(frozen=True)
class If:
    cond: object
    then_body: "Sequence"
    else_body: "Sequence"


@dataclass(frozen=True)
class While:
    cond: object
    body: "Sequence"
    bound: int | None = None


@dataclass(frozen=True)
class Assert:
    cond: object


@dataclass(frozen=True)
class Sequence:
    stmts: list[object]


@dataclass(frozen=True)
class HornClause:
    head_rel: str
    body_rel: str | None = None
    condition: object | None = None
    updates: dict[str, object] = field(default_factory=dict)
    comment: str = ""


@dataclass(frozen=True)
class Token:
    kind: str
    value: str
    position: int


TOKEN_RE = re.compile(
    r"""
    (?P<SPACE>\s+)
  | (?P<NUMBER>\d+)
  | (?P<OP><=|>=|==|!=|\+|-|\*|<|>|=)
  | (?P<PUNCT>[(){};\[\],])
  | (?P<IDENT>[A-Za-z_][A-Za-z0-9_]*)
    """,
    re.VERBOSE,
)


KEYWORDS = {"and", "assert", "bound", "else", "false", "if", "not", "or", "true", "var", "while"}


def _strip_comments(text: str) -> str:
    return re.sub(r"//.*", "", text)


class Parser:
    """Recursive-descent parser for the small imperative language."""

    def __init__(self, text: str):
        self.tokens = self._tokenize(_strip_comments(text))
        self.index = 0

    @staticmethod
    def _tokenize(text: str) -> list[Token]:
        tokens: list[Token] = []
        position = 0
        while position < len(text):
            match = TOKEN_RE.match(text, position)
            if match is None:
                snippet = text[position : position + 20]
                raise SyntaxError(f"unexpected token near {snippet!r}")
            position = match.end()
            kind = match.lastgroup
            value = match.group()
            if kind == "SPACE":
                continue
            if kind == "IDENT" and value in KEYWORDS:
                tokens.append(Token("KEYWORD", value, match.start()))
                continue
            if kind == "PUNCT":
                tokens.append(Token(value, value, match.start()))
                continue
            if kind == "OP":
                tokens.append(Token(value, value, match.start()))
                continue
            tokens.append(Token(kind or "", value, match.start()))
        tokens.append(Token("EOF", "", len(text)))
        return tokens

    def current(self) -> Token:
        return self.tokens[self.index]

    def advance(self) -> Token:
        token = self.current()
        self.index += 1
        return token

    def accept(self, value: str) -> bool:
        if self.current().value == value:
            self.advance()
            return True
        return False

    def expect(self, value: str) -> Token:
        token = self.current()
        if token.value != value:
            raise SyntaxError(f"expected {value!r} at position {token.position}, got {token.value!r}")
        return self.advance()

    def expect_kind(self, kind: str) -> Token:
        token = self.current()
        if token.kind != kind:
            raise SyntaxError(f"expected {kind} at position {token.position}, got {token.kind}")
        return self.advance()

    def parse_program(self) -> Sequence:
        statements = self.parse_statements(stop_tokens={"EOF"})
        self.expect_kind("EOF")
        return Sequence(statements)

    def parse_statements(self, stop_tokens: set[str]) -> list[object]:
        statements: list[object] = []
        while self.current().kind not in stop_tokens and self.current().value not in stop_tokens:
            statements.append(self.parse_statement())
        return statements

    def parse_statement(self) -> object:
        token = self.current()
        if token.value == "var":
            self.advance()
            name = self.expect_kind("IDENT").value
            self.expect("=")
            expr = self.parse_expression()
            self.expect(";")
            return Assign(name, expr)
        if token.value == "if":
            return self.parse_if()
        if token.value == "while":
            return self.parse_while()
        if token.value == "assert":
            self.advance()
            self.expect("(")
            cond = self.parse_expression()
            self.expect(")")
            self.expect(";")
            return Assert(cond)
        if token.kind == "IDENT":
            name = self.advance().value
            self.expect("=")
            expr = self.parse_expression()
            self.expect(";")
            return Assign(name, expr)
        raise SyntaxError(f"unexpected statement token {token.value!r} at position {token.position}")

    def parse_if(self) -> If:
        self.expect("if")
        self.expect("(")
        cond = self.parse_expression()
        self.expect(")")
        then_body = self.parse_block()
        else_body = Sequence([])
        if self.accept("else"):
            else_body = self.parse_block()
        return If(cond, then_body, else_body)

    def parse_while(self) -> While:
        self.expect("while")
        self.expect("(")
        cond = self.parse_expression()
        self.expect(")")
        bound = self.parse_optional_bound()
        body = self.parse_block()
        return While(cond, body, bound)

    def parse_optional_bound(self) -> int | None:
        if self.accept("["):
            self.expect("bound")
            self.expect("=")
            value = int(self.expect_kind("NUMBER").value)
            self.expect("]")
            return value
        if self.accept("bound"):
            return int(self.expect_kind("NUMBER").value)
        return None

    def parse_block(self) -> Sequence:
        self.expect("{")
        statements = self.parse_statements(stop_tokens={"}"})
        self.expect("}")
        return Sequence(statements)

    def parse_expression(self) -> object:
        return self.parse_or()

    def parse_or(self) -> object:
        expr = self.parse_and()
        while self.accept("or"):
            expr = BinOp("or", expr, self.parse_and())
        return expr

    def parse_and(self) -> object:
        expr = self.parse_not()
        while self.accept("and"):
            expr = BinOp("and", expr, self.parse_not())
        return expr

    def parse_not(self) -> object:
        if self.accept("not"):
            return BinOp("not", self.parse_not())
        return self.parse_comparison()

    def parse_comparison(self) -> object:
        expr = self.parse_additive()
        while self.current().value in {"<", "<=", "==", "!=", ">", ">="}:
            op = self.advance().value
            expr = BinOp(op, expr, self.parse_additive())
        return expr

    def parse_additive(self) -> object:
        expr = self.parse_term()
        while self.current().value in {"+", "-"}:
            op = self.advance().value

"""Experiment driver for the Horn translator and verifier."""

from __future__ import annotations

from time import perf_counter

from framework import report_result
from verification.horn_translator import HornEncoder, parse_program, verify_program


PROGRAMS = {
    "simple_counter": """
        var x = 0;
        while (x < 10) {
            x = x + 1;
        }
        assert(x == 10);
    """,
    "sum_accumulator": """
        var s = 0;
        var i = 0;
        while (i < 5) {
            s = s + i;
            i = i + 1;
        }
        assert(s >= 0);
    """,
    "branch_test": """
        var x = 5;
        if (x > 3) {
            x = x - 1;
        } else {
            x = x + 1;
        }
        assert(x >= 0);
    """,
    "unsafe_loop": """
        var x = 0;
        while (x < 100) {
            x = x + 2;
        }
        assert(x < 50);
    """,
    "nested_arithmetic": """
        var a = 1;
        var b = 2;
        a = a + b;
        b = a * 2;
        assert(b == 6);
    """,
}


def _translation_metrics(program_text: str) -> tuple[int, float]:
    start = perf_counter()
    ast = parse_program(program_text)
    encoder = HornEncoder()
    clauses = encoder.encode_program(ast)
    elapsed = perf_counter() - start
    return len(clauses), elapsed


def run_horn_experiments() -> dict[str, int | str]:
    """Run translation and verification experiments for the Horn layer."""

    total_clauses = 0
    translation_time = 0.0
    safe_count = 0
    unsafe_count = 0
    loop_invariants = 0

    for program_text in PROGRAMS.values():
        clause_count, elapsed = _translation_metrics(program_text)
        result = verify_program(program_text)
        total_clauses += clause_count
        translation_time += elapsed
        safe_count += 1 if result["safe"] else 0
        unsafe_count += 0 if result["safe"] else 1
        loop_invariants += int(result["loop_invariants"])

    results: dict[str, int | str] = {
        "HORN_CLAUSES_GENERATED": total_clauses,
        "HORN_PROGRAMS_VERIFIED": safe_count,
        "HORN_PROGRAMS_UNSAFE": unsafe_count,
        "HORN_LOOP_INVARIANTS": loop_invariants,
        "HORN_TRANSLATION_TIME": f"{translation_time:.2f}",
    }
    for key, value in results.items():
        report_result(key, value)
    return results


__all__ = ["PROGRAMS", "run_horn_experiments"]
